import { Group, Mesh, PlaneGeometry, DoubleSide, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  smoothstep,
  uniform,
  color,
  texture,
  fract,
  sin,
  dot,
  length,
  clamp,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();
  group.name = 'features-card-1';

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const cardW = 2.3;
  const cardH = 1.44;

  // --- Depth plane 0: engineered gradient backing (frame) -------------------
  const backW = cardW + 0.16;
  const backH = cardH + 0.16;
  const backGeo = new PlaneGeometry(backW, backH, 1, 1);
  const backMat = new MeshStandardNodeMaterial({ side: DoubleSide });
  const backUv = uv();
  const inkC = color(colors.ink);
  const surfC = color(colors.surface);
  const backGradient = mix(surfC, inkC, smoothstep(0.0, 1.0, backUv.y));
  backMat.colorNode = backGradient;
  backMat.roughness = 0.6;
  backMat.metalness = 0.5;
  backMat.clearcoat = 0.2;
  backMat.clearcoatRoughness = 0.4;
  const backMesh = new Mesh(backGeo, backMat);
  backMesh.position.set(0, 0, -0.02);
  group.add(backMesh);

  // --- Depth plane 1: contact shadow (grounding) -----------------------------
  const shadowGeo = new PlaneGeometry(backW * 1.35, backH * 1.2, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const sUv = uv().sub(vec2(0.5, 0.5));
  const dist = length(sUv.mul(vec2(1.0, 1.6)));
  const shadowAlpha = clamp(smoothstep(0.5, 0.0, dist), 0.0, 1.0).mul(0.5);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = shadowAlpha;
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -backH / 2 - 0.02, 0.35);
  group.add(shadowMesh);

  // --- Depth plane 2: the image card itself ----------------------------------
  const cardGeo = new PlaneGeometry(cardW, cardH, 1, 1);
  const cardMat = new MeshStandardNodeMaterial({ side: DoubleSide });
  cardMat.roughness = 0.55;
  cardMat.metalness = 0.12;
  cardMat.clearcoat = 0.15;
  cardMat.clearcoatRoughness = 0.5;

  // subtle grain uniform-driven noise, engineered (not soft blur)
  const grainAmount = uniform(0.035);
  const grainUv = uv().mul(vec2(900.0, 900.0));
  const grainNoise = fract(sin(dot(grainUv, vec2(12.9898, 78.233))).mul(43758.5453));
  const grainSigned = grainNoise.sub(0.5).mul(grainAmount);

  // fallback flat tint while texture loads (paper-tinted ink so it never reads FLAT_VOID black)
  const fallbackTint = mix(color(colors.ink), color(colors.surface), smoothstep(0.0, 1.0, uv().y));
  cardMat.colorNode = fallbackTint.add(vec3(grainSigned, grainSigned, grainSigned));

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0.02);
  group.add(cardMesh);

  let loadedTexture = null;
  const imageUrl = config?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader
      .loadTexture(imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        const texNode = texture(tex, uv());
        cardMat.colorNode = texNode.add(vec3(grainSigned, grainSigned, grainSigned));
        cardMat.needsUpdate = true;
      })
      .catch(() => {
        // keep the engineered-gradient fallback; never leave a dead flat black plane
      });
  }

  // --- Fine accent edge line (single accent, <=10% of frame) -----------------
  const edgeGeo = new PlaneGeometry(cardW * 0.9, 0.02, 1, 1);
  const edgeMat = new MeshBasicNodeMaterial({ transparent: true });
  edgeMat.colorNode = color(colors.accent);
  edgeMat.opacityNode = uniform(0.85);
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(0, -cardH / 2 + 0.06, 0.03);
  group.add(edgeMesh);

  // --- Scene placement (position applied by adapter; keep local orientation) --
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // --- Weighted entrance motion (no perpetual multi-axis screensaver motion) --
  group.scale.set(0.96, 0.96, 0.96);
  group.position.y += 0.12;
  const tl = gsap.timeline();
  tl.to(group.position, {
    y: group.position.y - 0.12,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(
    group.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    },
    0.05
  );

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    backGeo.dispose();
    backMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();

    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }
  };

  return group;
}
